/// The ops every styled type shares (the token list and the traits that only write the style),
/// for the hand-written decoders of the runtime. False when `op` is none of them.
pub fn style_op(style: &mut gpui_kit::StyleRefinement, op: u16, r: &mut R, dx: &mut Dx) -> bool {
    match op {
        4 => style_tokens(style, r),
        16896..=17023 => { let _ = tr_styled_3(W(style), op, r, dx); }
        17792..=17919 => { let _ = tr_styled_ext_18(W(style), op, r, dx); }
        _ => return false,
    }
    true
}

/// A part of a described plot, painted in the plot's bounds when the plot paints.
pub type PaintFn = Box<dyn Fn(&gpui_kit::Bounds<gpui_kit::Pixels>, &mut gpui_kit::Window, &mut gpui_kit::App)>;

/// The value node `n` as a part of a plot; None when its type paints nothing (gk.plot checks it).
pub fn paint_part(dx: &mut Dx, n: u32) -> Option<PaintFn> {
    match dx.node(n).0 {
        527 | 528 => { let v = build_base_grid(dx, n)?; Some(Box::new(move |b: &gpui_kit::Bounds<gpui_kit::Pixels>, window: &mut gpui_kit::Window, cx: &mut gpui_kit::App| { let _ = &cx; <gpui_kit::base::plot::Grid>::paint(&v, b, window) })) }
        530 | 531 => { let v = build_base_plot_axis(dx, n)?; Some(Box::new(move |b: &gpui_kit::Bounds<gpui_kit::Pixels>, window: &mut gpui_kit::Window, cx: &mut gpui_kit::App| { let _ = &cx; <gpui_kit::base::plot::PlotAxis>::paint(&v, b, window, cx) })) }
        808 | 809 => { let v = build_base_area_shape(dx, n)?; Some(Box::new(move |b: &gpui_kit::Bounds<gpui_kit::Pixels>, window: &mut gpui_kit::Window, cx: &mut gpui_kit::App| { let _ = &cx; <gpui_kit::base::plot::shape::Area<crate::data::Datum>>::paint(&v, b, window) })) }
        810 | 811 => { let v = build_base_bar_shape(dx, n)?; Some(Box::new(move |b: &gpui_kit::Bounds<gpui_kit::Pixels>, window: &mut gpui_kit::Window, cx: &mut gpui_kit::App| { let _ = &cx; <gpui_kit::base::plot::shape::Bar<crate::data::Datum>>::paint(&v, b, window, cx) })) }
        812 | 813 => { let v = build_base_line_shape(dx, n)?; Some(Box::new(move |b: &gpui_kit::Bounds<gpui_kit::Pixels>, window: &mut gpui_kit::Window, cx: &mut gpui_kit::App| { let _ = &cx; <gpui_kit::base::plot::shape::Line<crate::data::Datum>>::paint(&v, b, window) })) }
        814 | 815 => { let v = build_base_radial_line_shape(dx, n)?; Some(Box::new(move |b: &gpui_kit::Bounds<gpui_kit::Pixels>, window: &mut gpui_kit::Window, cx: &mut gpui_kit::App| { let _ = &cx; <gpui_kit::base::plot::shape::RadialLine<crate::data::Datum>>::paint(&v, b, window) })) }
        _ => None,
    }
}

